    public class GEParamsController : BaseBusinessController
    {
        public GEParamsController()
        {
            dal = new DALBaseProvider("GEParams", typeof(GEParamsInfo));
        }

        /// <summary>
        /// Get the list of params based on some criteria
        /// </summary>
        /// <param name="paramName">Param name</param>
        /// <returns>List of params</returns>
        public IList<GEParamsInfo> GetParamList(string paramName)
        {
            DataSet ds = dal.GetDataSet("GEParams_GetParamList", paramName);
            IList<GEParamsInfo> result = new List<GEParamsInfo>();
            if (ds.Tables.Count > 0)
            {
                foreach (DataRow row in ds.Tables[0].Rows)
                {
                    GEParamsInfo objParamsInfo = (GEParamsInfo)GetObjectFromDataRow(row);
                    result.Add(objParamsInfo);
                }
            }
            return result;
        }

        /// <summary>
        /// Get the value collection of a param
        /// </summary>
        /// <param name="paramName">Param name</param>
        /// <returns></returns>
        public IList<GEParamsInfo> GetParamValuesByName(string paramName)
        {
            return GetParamList(paramName);
        }
    }
